        mov     ax, [listLump__i]
        mov     [wadPosHigh__lump], ax
        call    wadPosHigh
        mov     ax, [wadPosHigh__ret]
        push    ax                          ; argument evaluated before any is stored
        mov     ax, [listLump__i]
        mov     [wadPosLow__lump], ax
        call    wadPosLow
        mov     ax, [wadPosLow__ret]
