        mov     [right32__lo], ax
        pop     ax
        mov     [right32__hi], ax
        call    right32
; ---- right32( wadSizeHigh( i ), wadSizeLow( i ), 10 )
        mov     ax, [listLump__i]
        mov     [wadSizeHigh__lump], ax
        call    wadSizeHigh
        mov     ax, [wadSizeHigh__ret]
