        mov     word [right32__width], 10
        pop     ax
        mov     [right32__lo], ax
        pop     ax
        mov     [right32__hi], ax
        call    right32
; ---- spaces( 2 )
        mov     word [spaces__n], 2
        call    spaces
; ---- t = wadTypeOf( i )
        mov     ax, [listLump__i]
        mov     [wadTypeOf__lump], ax
        call    wadTypeOf
        mov     al, [wadTypeOf__ret]
