        mov     ax, [wadTypeName__ret]
        mov     [putStr__at], ax
        call    putStr
; ---- spaces( 9 - strLen( wadTypeName( t ) ) )
        mov     ax, 9
        push    ax                          ; save lhs: rhs is not a leaf
        mov     al, [listLump__t]
        mov     [wadTypeName__t], al        ; u8 -> u8, no widening
        call    wadTypeName
        mov     ax, [wadTypeName__ret]
        mov     [strLen__at], ax
        call    strLen
        mov     ax, [strLen__ret]
